// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product, Fixed18, PackedFixed18, PackedUFixed18, UFixed18, IOracleProvider, JumpRateUtilizationCurve, PayoffDefinition, PayoffDefinitionLib, IProduct} from "../src/Product.sol";

contract InvMutTest is Test {
    Product c;
    Env env;
    Oracle oracle;

    function setUp() public {
        c = new Product();
        oracle = new Oracle();
        env = new Env();
        env.doInitialize(address(c), address(oracle));
    }

    function testFuzz_property(uint256 newMaintenance, address actor) public {
        newMaintenance = bound(newMaintenance, 1, 1e24);
        vm.assume(actor != address(0));

        env.setProductOwner(actor);
        uint256 before = UFixed18.unwrap(c.maintenance());

        vm.prank(actor);
        bool ok;
        try c.updateMaintenance(UFixed18.wrap(newMaintenance)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: if the update succeeds, maintenance() must now equal the new value;
        //       if it reverts, maintenance() must remain unchanged.
        assertTrue(!ok || UFixed18.unwrap(c.maintenance()) == newMaintenance);
        // (unchanged-on-revert is subsumed: reference reverts only before any store)
        if (!ok) assertTrue(UFixed18.unwrap(c.maintenance()) == before);
    }
}

contract Oracle {
    function sync() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }

    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }

    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
}

contract Env {
    address public productOwner;

    function setProductOwner(address owner_) external {
        productOwner = owner_;
    }

    function doInitialize(address c_, address oracle_) external {
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "n",
            symbol: "s",
            payoffDefinition: PayoffDefinition(
                PayoffDefinitionLib.PayoffType(0),
                PayoffDefinitionLib.PayoffDirection(0),
                bytes30(0)
            ),
            oracle: IOracleProvider(oracle_),
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1e24),
            utilizationCurve: JumpRateUtilizationCurve(
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedUFixed18.wrap(0)
            )
        });
        IProduct(c_).initialize(info);
    }

    function isProduct(IProduct) external pure returns (bool) {
        return true;
    }

    function coordinatorFor(IProduct) external pure returns (uint256) {
        return 1;
    }

    function owner(uint256) external view returns (address) {
        return productOwner;
    }

    function paused() external pure returns (bool) {
        return false;
    }
}
